"""Use LLM-as-a-judge to evaluate creative responses generated by LLMs during inference
"""
import argparse
import logging
import os
from src.utils.helpers import load_json, save_json
import pandas as pd
from tqdm import tqdm
import random
from src.utils.api_wrapper import ModelWrapper
from src.utils.rubrics import ttct_rubrics
from src.utils.demo import llmj_demo_data
from src.evaluation.eval_prompts import (
    EVAL_PROMPT, 
    EXAMPLE_PROMPT, 
    PAIRWISE_PROMPT, 
    EVAL_W_SUMMARY_PROMPT
)

MAX_TOKENS = 1024
DEFAULT_SUBSET = [
    '1_unusual_uses', '5_common_problems', '4_situation', '6_improvement', '2_consequences'
]
def csv2json(csv_data, subset = []):
    input_data = pd.read_csv('/ihome/xli/joh227/developer/creativityprism_git_workspace/tasks/ttct/data/outputs/basefile.csv')
    assert len(csv_data) == len(input_data)

    json_data = []
    for i, row in csv_data.iterrows():
        tmp_data = {'input': {}, 'output': {}}
        tmp_data['input']['text_basic'] = input_data.iloc[i]['infer_basic_input']
        tmp_data['input']['text_instructive'] = input_data.iloc[i]['infer_instructive_input']
        tmp_data['input']['text_cot'] = input_data.iloc[i]['infer_cot_input']
        tmp_data['output']['text_basic'] = row['infer_basic_pred']
        tmp_data['output']['text_instructive'] = row['infer_instructive_pred']
        tmp_data['output']['text_cot'] = row['infer_cot_pred']
        tmp_data['question_type'] = input_data.iloc[i]['question_type']
        if len(subset) > 0 and tmp_data['question_type'] not in subset:
            tmp_data['skip'] = True
        elif 'skip' in row:
            tmp_data['skip'] = True if row['skip'] == 1 else False
        else:
            tmp_data['skip'] = False
        json_data.append(tmp_data)
    print('Number of skipped items so far:', sum([1 for item in json_data if item.get('skip', False)]), '/', len(json_data))
    return json_data

def json2csv(json_data):
    # infer_basic_input,infer_basic_pred,infer_instructive_input,infer_cot_input,infer_instructive_pred,infer_cot_pred
    csv_data = []
    for item in json_data:
        tmp_data = {}
        tmp_data['infer_basic_input'] = item['input']['text_basic']
        tmp_data['infer_basic_pred'] = item['output']['text_basic']
        tmp_data['infer_instructive_input'] = item['input']['text_instructive']
        tmp_data['infer_instructive_pred'] = item['output']['text_instructive']
        tmp_data['infer_cot_input'] = item['input']['text_cot']
        tmp_data['infer_cot_pred'] = item['output']['text_cot']
        if 'skip' in item:
            tmp_data['skip'] = 1 if item['skip'] else 0
        else:
            tmp_data['skip'] = 0
        csv_data.append(tmp_data)

    # Create a DataFrame from the CSV data
    df = pd.DataFrame(csv_data)
    return df

def main(infer_model_name, eval_model_name, temp, cache_dir, demo, pairwise, summary, api_key_path, subset, run_id=""):
    logger = logging.getLogger(__name__)

    # Load creative questions from original paper
    # data_path = f'data/outputs/temp_{temp}/{infer_model_name}.json'
    # data = load_json(data_path)

    if run_id != "":
        data_fp = f'data/outputs/{run_id}/'
    else:
        data_fp = f'data/outputs/temp_{temp}/'

    print(infer_model_name, eval_model_name, data_fp)
    print('Files found:', os.listdir(data_fp))
    if f'{infer_model_name}.csv' in os.listdir(data_fp):
        print('Loading CSV inference results and convert to JSON format')
        data_path = f'{data_fp}{infer_model_name}.csv'
        data = csv2json(pd.read_csv(data_path), subset)
    elif f'{infer_model_name.strip()}.json' in os.listdir(data_fp):
        print('Loading JSON inference results and convert to CSV format then back to JSON format')
        data_path = f'{data_fp}{infer_model_name}.json'
        data = json2csv(load_json(data_path))
        data = csv2json(data, subset)
    else:
        raise FileNotFoundError(f'No inference results found for model {infer_model_name} at {data_fp}')
    

    # Load model using 4 GPUs
    if 'gpt' in eval_model_name.lower() or 'gemini' in eval_model_name.lower():
        api_key = load_json(api_key_path) 
        llm = ModelWrapper(
            model_name=eval_model_name, 
            api_key=api_key[eval_model_name.lower()],
        )
        use_open_model = False
        llm.temperature = 0.0
        llm.max_tokens = MAX_TOKENS
    else:
        use_open_model = True
        from vllm import LLM, SamplingParams
        llm = LLM(
            # model=f'{cache_dir}/{eval_model_name}', 
            model=f'{eval_model_name}',
            tensor_parallel_size=4,        
            gpu_memory_utilization=0.9, 
            max_model_len=MAX_TOKENS * 8
        )

    # preparing inputs for evaluation
    for item in data:
        # assert 'question_type' in item, "Each data item must have a 'question_type' field."
        
        if pairwise:
            question_type = item['question_type']
            item['eval_input'] = {}

            # TODO: add code to handle basic and instructive cases
            # prepare questions and responses for pairwise evaluation
            order = random.choice([0, 1])
            cot_question = item['input'][f'text_cot'] if not item.get('skip', False) else "SKIPPED"
            cot_prediction = item['output'][f'text_cot'] if not item.get('skip', False) else "SKIPPED"
            if item['question_type'] in llmj_demo_data:
                ref_question = llmj_demo_data[item['question_type']]['highest']['question']
                ref_prediction = llmj_demo_data[item['question_type']]['highest']['answer']
            else:
                ref_question = ''
                ref_prediction = ''
            if order:
                item['eval_input']['target'] = 'A'
                item['eval_input']['pairwise_data'] = PAIRWISE_RESPONSES.format(
                    question_a=cot_question,
                    response_a=cot_prediction,
                    question_b=ref_question,
                    response_b=ref_prediction,
                )
            else:
                item['eval_input']['pairwise_data'] = PAIRWISE_RESPONSES.format(
                    question_a=ref_question,
                    response_a=ref_prediction,
                    question_b=cot_question,
                    response_b=cot_prediction,
                )
                item['eval_input']['target'] = 'B'
            item['eval_input']['prompt_head'] = PAIRWISE_PROMPT.format(
                name=ttct_rubrics[question_type]['name'],
                definition=ttct_rubrics[question_type]['definition'],
                # example=ttct_rubrics[question_type]['example'],
                fluency_rubric=ttct_rubrics[question_type]['dimensions']['Fluency'],
                fluency_details=''.join([
                    "{}: {}\n".format(key, ttct_rubrics[question_type]['scale'][key]['Fluency'])
                    for key in ["1", "2", "3", "4", "5"]
                ]),
                flexibility_rubric=ttct_rubrics[question_type]['dimensions']['Flexibility'],
                flexibility_details=''.join([
                    "{}: {}\n".format(key, ttct_rubrics[question_type]['scale'][key]['Flexibility'])
                    for key in ["1", "2", "3", "4", "5"]
                ]),
                originality_rubric=ttct_rubrics[question_type]['dimensions']['Originality'],
                originality_details=''.join([
                    "{}: {}\n".format(key, ttct_rubrics[question_type]['scale'][key]['Originality'])
                    for key in ["1", "2", "3", "4", "5"]
                ]),
                elaboration_rubric=ttct_rubrics[question_type]['dimensions']['Elaboration'],
                elaboration_details=''.join([
                    "{}: {}\n".format(key, ttct_rubrics[question_type]['scale'][key]['Elaboration'])
                    for key in ["1", "2", "3", "4", "5"]
                ])
            )
            item['eval_input']['cot_inputs'] = item['eval_input']['prompt_head'] + item['eval_input']['pairwise_data'] if not item.get('skip', False) else "SKIPPED"
            
        else:
            if demo and item['question_type'] in llmj_demo_data:
                demo_examples = llmj_demo_data[item['question_type']]
                demo_example_str = '''\n====================\nEXAMPLE RATINGS\n====================\nHere are some example ratings for your reference:'''
                for level in ['highest', 'median', 'lowest']:
                    demo_example_str += f'Score level: {level}:\n'  + EXAMPLE_PROMPT.format(**demo_examples[level]) + '\n\n'
            else:
                demo_example_str = ''
            
            if summary:
                eval_prompt_template = EVAL_W_SUMMARY_PROMPT
            else:
                eval_prompt_template = EVAL_PROMPT
            question_type = item['question_type']
            item['eval_input'] = {}
            item['eval_input']['prompt_head'] = eval_prompt_template.format(
                name=ttct_rubrics[question_type]['name'],
                definition=ttct_rubrics[question_type]['definition'],
                # example=ttct_rubrics[question_type]['example'],
                fluency_rubric=ttct_rubrics[question_type]['dimensions']['Fluency'],
                fluency_details=''.join([
                    "{}: {}\n".format(key, ttct_rubrics[question_type]['scale'][key]['Fluency'])
                    for key in ["1", "2", "3", "4", "5"]
                ]),
                flexibility_rubric=ttct_rubrics[question_type]['dimensions']['Flexibility'],
                flexibility_details=''.join([
                    "{}: {}\n".format(key, ttct_rubrics[question_type]['scale'][key]['Flexibility'])
                    for key in ["1", "2", "3", "4", "5"]
                ]),
                originality_rubric=ttct_rubrics[question_type]['dimensions']['Originality'],
                originality_details=''.join([
                    "{}: {}\n".format(key, ttct_rubrics[question_type]['scale'][key]['Originality'])
                    for key in ["1", "2", "3", "4", "5"]
                ]),
                elaboration_rubric=ttct_rubrics[question_type]['dimensions']['Elaboration'],
                elaboration_details=''.join([
                    "{}: {}\n".format(key, ttct_rubrics[question_type]['scale'][key]['Elaboration'])
                    for key in ["1", "2", "3", "4", "5"]
                ]),
                demo_examples=demo_example_str
            ) 

            basic_question = item['input'][f'text_basic'] if not item.get('skip', False) else "SKIPPED"
            basic_prediction = item['output'][f'text_basic'] if not item.get('skip', False) else "SKIPPED"
            item['eval_input']['basic_inputs'] = f'''{item["eval_input"]["prompt_head"]}\nQuestion: {basic_question}\nAnswer: {basic_prediction}\n\nANSWER RATINGS ON FOUR DIMENSIONS:''' if not item.get('skip', False) else "SKIPPED"

            instructive_question = item['input'][f'text_instructive'] if not item.get('skip', False) else "SKIPPED"
            instructive_prediction = item['output'][f'text_instructive'] if not item.get('skip', False) else "SKIPPED"
            item['eval_input']['instructive_inputs'] = f'''{item["eval_input"]["prompt_head"]}\nQuestion: {instructive_question}\nAnswer: {instructive_prediction}\n\nANSWER RATINGS ON FOUR DIMENSIONS:''' if not item.get('skip', False) else "SKIPPED"

            cot_question = item['input'][f'text_cot'] if not item.get('skip', False) else "SKIPPED"
            cot_prediction = item['output'][f'text_cot'] if not item.get('skip', False) else "SKIPPED"
            item['eval_input']['cot_inputs'] = f'''{item["eval_input"]["prompt_head"]}\nQuestion: {cot_question}\nAnswer: {cot_prediction}\n\nANSWER RATINGS ON FOUR DIMENSIONS:''' if not item.get('skip', False) else "SKIPPED"

    # Use hyperparameters from original paper, section 4.1.2 (temperature is variable for additional experiments)
    if use_open_model:
        sampling_params = SamplingParams(
            max_tokens=MAX_TOKENS,
            temperature=0.0,
            top_p=1.0,
            top_k=50
        )

        # logger.info(f'Running evaluations on basic type prompts')
        # basic_eval_pred = llm.generate(basic_inputs, sampling_params)
        # basic_eval_pred = [output.outputs[0].text for output in basic_eval_pred]

        # logger.info(f'Running evaluations on instructive type prompts')
        # instructive_eval_pred = llm.generate(instructive_inputs, sampling_params)
        # instructive_eval_pred = [output.outputs[0].text for output in instructive_eval_pred]

        # logger.info(f'Running evaluations on cot type prompts')
        # cot_eval_pred = llm.generate(cot_inputs, sampling_params)
        # cot_eval_pred = [output.outputs[0].text for output in cot_eval_pred]


        # TODO: change this 
        # logger.info(f'Running evaluations on basic type prompts')
        # basic_eval_pred = llm.generate(basic_inputs, sampling_params)
        basic_eval_pred = ["SKIPPED" for _ in data]

        # TODO: change this
        # logger.info(f'Running evaluations on instructive type prompts')
        # instructive_eval_pred = llm.generate(instructive_inputs, sampling_params)
        instructive_eval_pred = ["SKIPPED" for _ in data]

        logger.info(f'Running evaluations on cot type prompts')
        print('Starting CoT evaluations, count:', len([item for item in data if item['eval_input']['cot_inputs'] != "SKIPPED"]))
        
        # unskipped_idx = [i for i, item in enumerate(data) if not item.get('skip', False)]
        unskipped_inputs = [item['eval_input']['cot_inputs'] for item in data if not item.get('skip', False)]
        unskipped_outputs = llm.generate(unskipped_inputs, sampling_params)
        unskipped_texts = [output.outputs[0].text for output in unskipped_outputs]
        cot_eval_pred = []
        unskipped_counter = 0
        for i, item in enumerate(data):
            if item.get('skip', False):
                cot_eval_pred.append("SKIPPED")
            else:
                cot_eval_pred.append(unskipped_texts[unskipped_counter])
                unskipped_counter += 1

    else:
        # TODO: change this 
        # logger.info(f'Running evaluations on basic type prompts')
        # basic_eval_pred = llm.generate(basic_inputs, sampling_params)
        basic_eval_pred = ["SKIPPED" for _ in data]

        # TODO: change this 
        # logger.info(f'Running evaluations on instructive type prompts')
        # instructive_eval_pred = llm.generate(instructive_inputs, sampling_params)
        instructive_eval_pred = ["SKIPPED" for _ in data]

        logger.info(f'Running evaluations on cot type prompts')
        # print('Starting CoT evaluations, count:', len([item for item in data if item['eval_input']['cot_inputs'] != "SKIPPED"]))
        cot_eval_pred = [
            llm.generate_response(item['eval_input']['cot_inputs']) 
            if item['eval_input']['cot_inputs'] != "SKIPPED" else "SKIPPED" 
            for item in tqdm(data)
        ]

    for i, item in enumerate(data):
        item["evaluation"] = {
            f"text_basic": basic_eval_pred[i],
            f"text_instructive": instructive_eval_pred[i],
            f"text_cot": cot_eval_pred[i],
        }
    data = [item for item in data if not item.get('skip', False)] # remove skipped items

    # Save the updated data to a JSON file
    if run_id != "":
        eval_file_name = f'data/evaluations/{run_id}/{infer_model_name}.json'
    else:
        eval_file_name = f'data/evaluations/temp_{temp}/{infer_model_name}.json'
    save_json(data, eval_file_name)
    logger.info(f"Evaluation for {infer_model_name} completed using {eval_model_name}.")


if __name__ == "__main__":

    parser = argparse.ArgumentParser(description='Conduct evaluation on creative outputs from LLMs (using LLM-as-a-judge).')

    parser.add_argument('-infer_model_name', 
                        type=str, 
                        default='Qwen2.5-72B-Instruct', 
                        help=f'Name of LLM being evaluated (should match name of local directory where weights are stored)'
                        )
    
    parser.add_argument('-eval_model_name', 
                        type=str, 
                        default='Qwen2.5-72B-Instruct', 
                        help=f'Name of LLM used to evaluate (should match name of local directory where weights are stored)'
                        )
    
    parser.add_argument('-temp', 
                        type=int, 
                        default=1, 
                        help=f'Original temp=1; however, it is variable here for additional experiments'
                        )
    
    parser.add_argument('-run_id', 
                        type=str, 
                        default="", 
                        help=f'Additional identifier for this evaluation run (appended to output filename)'
                        )
    
    parser.add_argument('-cache_dir', 
                        type=str, 
                        default='/playpen-ssd/pretrained_models', 
                        help=f'Path to local directory containing model weights'
                        )
    parser.add_argument('-demo',
                        type=bool, 
                        default=False, 
                        help=f'Whether to run evaluation with few-shot demostrations.'
                        )
    parser.add_argument('-pairwise',
                        type=bool,
                        default=False,
                        help=f'Whether to run pairwise evaluation.'
                        )
    parser.add_argument('-summary',
                        type=bool,
                        default=False,
                        help=f'Whether to run summarization before evaluation.'
                        )
    parser.add_argument('-api_key_path',
                        type=str,
                        default='/ihome/xli/joh227/developer/creativityprism_git_workspace/api_keys.json',
                        help=f'Path to API key json file.'
                        )
    # parser.add_argument('-multi_time',
    #                     type=bool,
    #                     default=False,
    #                     help=f'Whether to run multiple rounds of prompting during evaluation.'
    #                     )
    parser.add_argument('-subset', 
                        type=list, 
                        default=DEFAULT_SUBSET, 
                        help=f'List of subsets to include in the evaluation'
                        )
    args = parser.parse_args()
    main(**vars(args)) 